"use client";

import { useEffect, useRef, useState } from "react";
import type { CSSProperties, HTMLAttributes } from "react";

export interface BarStreamProps extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** Number of bars around the ring (12–72). */
  bars?: number;
  /** Resting height of each bar in px, pointing out from the center. */
  barHeight?: number;
  /** Thickness of each bar in px. */
  barWidth?: number;
  /** Corner radius of each bar in px. */
  radius?: number;
  /** How far each pulse grows a bar, in px. The end away from the push never moves. */
  extend?: number;
  /** Seconds one pulse takes to pass a bar. */
  duration?: number;
  /** Seconds between one bar pulsing and the next, going clockwise. */
  stagger?: number;
  /** Which way the push carries a bar: `out` away from the center, `in` toward it. */
  direction?: BarDirection;
  /** Canvas size in px (the loader is square). */
  size?: number;
  /** Bar color, any CSS color. */
  color?: string;
  /** Opacity of resting bars (0–1). Bars at the peak of the push are always 1. */
  minOpacity?: number;
  /** Coast to a stop on the current frame. Turning it back off eases the animation back up to speed. */
  paused?: boolean;
  /** Accessible name; the wrapper is role="status". */
  label?: string;
}

function scene() {
  return barScene<BarSettings, never>(() => ({ stream: 1 }));
}

export function BarStream({
  bars = 36,
  barHeight = 12,
  barWidth = 2,
  radius = 1,
  extend = 10,
  duration = 0.08,
  stagger = 0.03,
  direction = "out",
  size = 160,
  color = "#e4e4e7",
  minOpacity = 0.35,
  paused = false,
  label = "Loading",
  ...rest
}: BarStreamProps) {
  const settings: BarSettings = { bars, barHeight, barWidth, radius, extend, duration, stagger, direction, size, color, minOpacity, paused };
  return <LoaderCanvas settings={settings} targets={barTargets} shape={barShape} settle={barSettle} scene={scene} label={label} {...rest} />;
}

export default BarStream;

let probe: CanvasRenderingContext2D | null = null;

/** Resolves any CSS color to sRGB [r, g, b, a] by painting it into one pixel, so it can be blended. */
function parseColor(color: string): [number, number, number, number] {
  probe ??= document.createElement("canvas").getContext("2d", { willReadFrequently: true });
  if (!probe) return [228, 228, 231, 1];
  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = "#000"; // An invalid color leaves fillStyle as it was, so start from a known one.
  probe.fillStyle = color;
  probe.fillRect(0, 0, 1, 1);
  const [r, g, b, a] = probe.getImageData(0, 0, 1, 1).data;
  return [r, g, b, a / 255];
}

/** A CSS color as glide targets, so a color change blends instead of jumping. */
function colorTargets(color: string) {
  const [red, green, blue, alpha] = parseColor(color);
  return { red, green, blue, alpha };
}

/** The blended color as an opaque CSS color; its alpha is applied per dot through globalAlpha. */
function rgb(v: { red: number; green: number; blue: number }) {
  return `rgb(${v.red} ${v.green} ${v.blue})`;
}

/** A CSS `cubic-bezier(x1, y1, x2, y2)` as a function of progress 0..1. */
function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  const ax = 3 * x1 - 3 * x2 + 1;
  const bx = 3 * x2 - 6 * x1;
  const cx = 3 * x1;
  const ay = 3 * y1 - 3 * y2 + 1;
  const by = 3 * y2 - 6 * y1;
  const cy = 3 * y1;
  const curveX = (s: number) => ((ax * s + bx) * s + cx) * s;
  const curveY = (s: number) => ((ay * s + by) * s + cy) * s;
  const slopeX = (s: number) => (3 * ax * s + 2 * bx) * s + cx;
  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    // Newton's method finds the curve parameter whose x is `t`; bisection catches the flat spots.
    let s = t;
    for (let i = 0; i < 6; i++) {
      const dx = curveX(s) - t;
      const slope = slopeX(s);
      if (Math.abs(dx) < 1e-6) return curveY(s);
      if (Math.abs(slope) < 1e-6) break;
      s -= dx / slope;
    }
    let lo = 0;
    let hi = 1;
    s = t;
    for (let i = 0; i < 20; i++) {
      const x = curveX(s);
      if (Math.abs(x - t) < 1e-6) break;
      if (x < t) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
    }
    return curveY(s);
  };
}

/** Strong ease-out, `cubic-bezier(0.23, 1, 0.32, 1)`: for things arriving or leaving. */
const easeOut = cubicBezier(0.23, 1, 0.32, 1);

/** Strong ease-in-out, `cubic-bezier(0.77, 0, 0.175, 1)`: for things moving or morphing on screen. */
const easeInOut = cubicBezier(0.77, 0, 0.175, 1);

/**
 * Glide times are a spring's time constant, not a duration: a glide is about 90% of the way to its target
 * after twice its time, so `SETTLE` reads as a ~240ms change.
 */

/** Seconds (roughly) a changed prop takes to glide to its new value: size, spacing, timing and the like. */
const SETTLE = 0.12;

/** Color and opacity: faster, since nothing moves (~150ms). */
const FADE_SETTLE = 0.075;

/** Changing animation: one motion blending into the next (~300ms). */
const BLEND_SETTLE = 0.15;

/** Pausing: seconds (roughly) the animation takes to coast to a stop (~300ms). */
const STOP_SETTLE = 0.15;

/** Resuming: seconds (roughly) the animation takes to get back up to speed (~400ms). */
const START_SETTLE = 0.2;

/** A value that glides toward its target on a critically damped spring: no jump, no overshoot. */
type Glide = { value: number; velocity: number; target: number };

function glide(value: number): Glide {
  return { value, velocity: 0, target: value };
}

function snap(g: Glide) {
  g.value = g.target;
  g.velocity = 0;
}

/** Moves `g` toward its target. Returns false once it has arrived and is at rest. */
function stepGlide(g: Glide, dt: number, time: number) {
  if (g.value === g.target && g.velocity === 0) return false;
  const omega = 2 / time;
  const x = omega * dt;
  const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
  const change = g.value - g.target;
  const temp = (g.velocity + omega * change) * dt;
  g.velocity = (g.velocity - omega * temp) * decay;
  g.value = g.target + (change + temp) * decay;
  if (Math.abs(g.value - g.target) < 1e-3 && Math.abs(g.velocity) < 1e-3) snap(g);
  return true;
}

/** The glided value of every target, plus the canvas `size` and the pause `rate` (0 paused, 1 running). */
type Values<K extends string> = Record<K | "size" | "rate", number>;

/** What a scene sees each frame. `layers` holds every shape on screen; more than one while a change cross-fades. */
interface Frame<S, K extends string, L> {
  settings: S;
  v: Values<K>;
  layers: { shape: L; fade: number }[];
  size: number;
  /** The viewer asked for reduced motion: the clock holds still, so a scene that ends somewhere should jump there. */
  reduced: boolean;
}

interface Scene<S, K extends string, L> {
  /** Moves the scene's own clock on by `dt` seconds. Scale by `v.rate` so pausing coasts to a stop. */
  advance?(dt: number, frame: Frame<S, K, L>): void;
  /** Paints one frame onto a cleared canvas, already scaled to `size` px. */
  draw(ctx: CanvasRenderingContext2D, frame: Frame<S, K, L>): void;
}

interface LoaderCanvasProps<S extends { size: number; paused: boolean }, K extends string, L>
  extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** The latest props. Read by `targets` and `shape` on every render, and by the scene every frame. */
  settings: S;
  /** Every number the scene reads, as the latest settings want it. Each glides to its new value. */
  targets: (s: NoInfer<S>) => Record<K, number>;
  /**
   * Geometry rebuilt when its key changes. The old shape's fade glides to 0 while the new one's glides to 1:
   * a plain cross-fade, unless `morph` links the two so the scene can move one into the other.
   */
  shape?: {
    key: (s: NoInfer<S>) => string;
    build: (s: NoInfer<S>) => L;
    /** Called when `to` replaces `from`, whose fade is `fade` at that moment. */
    morph?: (from: L, to: L, fade: number) => void;
    /** Seconds (roughly) a shape change takes. Defaults to `BLEND_SETTLE`. */
    settle?: number;
  };
  /** Seconds (roughly) each target takes to glide to a new value, by key. Unlisted keys take `SETTLE`. */
  settle?: Partial<Record<NoInfer<K> | "size", number>>;
  /** Seconds (roughly) pausing takes to coast to a stop, and resuming to get back up to speed. */
  pause?: { stop: number; start: number };
  /** Called once on mount; the returned scene keeps its own clock between frames. */
  scene: () => Scene<NoInfer<S>, K, L>;
  label: string;
}

/**
 * A square canvas that runs a scene: props glide instead of jumping, pausing coasts, shape changes
 * cross-fade or morph, reduced motion holds still, and the loop sleeps once nothing is moving.
 */
function LoaderCanvas<S extends { size: number; paused: boolean }, K extends string, L>({
  settings,
  targets,
  shape,
  settle,
  pause,
  scene,
  label,
  className,
  style,
  ...rest
}: LoaderCanvasProps<S, K, L>) {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // Only the first size reaches the DOM through React; after that the loop glides it.
  const [initialSize] = useState(settings.size);
  const latest = useRef({ settings, targets, shape, settle, pause, scene });
  const wakeRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    latest.current = { settings, targets, shape, settle, pause, scene };
    wakeRef.current?.();
  });

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!wrapper || !canvas || !ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const { settings: first, shape: shapeOf, scene: makeScene } = latest.current;
    const sceneNow = makeScene();
    const glides = {} as Record<string, Glide>;
    const v = {} as Values<K>;
    let shapes = shapeOf ? [{ key: shapeOf.key(first), shape: shapeOf.build(first), fade: glide(1) }] : [];
    const frameInfo: Frame<S, K, L> = { settings: first, v, layers: [], size: 1, reduced: reduceMotion.matches };
    let shownSize = -1;
    let frame = 0;
    let last = 0;
    // Off screen or in a hidden tab, the loop sleeps; it picks up where it left off once seen again.
    let onScreen = true;
    const visible = () => onScreen && document.visibilityState === "visible";

    const targetsNow = () => {
      const { settings: s, targets } = latest.current;
      return { ...targets(s), size: s.size, rate: s.paused ? 0 : 1 } as Record<string, number>;
    };
    for (const [k, value] of Object.entries(targetsNow())) glides[k] = glide(value);

    /** Refreshes what the scene reads from the glides and shapes. */
    const read = () => {
      for (const k in glides) (v as Record<string, number>)[k] = glides[k].value;
      frameInfo.settings = latest.current.settings;
      frameInfo.layers = shapes.map(({ shape, fade }) => ({ shape, fade: fade.value }));
      frameInfo.size = Math.max(1, v.size);
      frameInfo.reduced = reduceMotion.matches;
    };

    const sync = () => {
      const { settings: s, shape: shapeOf } = latest.current;
      for (const [k, value] of Object.entries(targetsNow())) glides[k].target = value;
      if (shapeOf) {
        const key = shapeOf.key(s);
        if (key !== shapes[shapes.length - 1].key) {
          for (const shape of shapes) shape.fade.target = 0;
          const fade = glide(0);
          fade.target = 1;
          const prev = shapes[shapes.length - 1];
          const next = { key, shape: shapeOf.build(s), fade };
          shapeOf.morph?.(prev.shape, next.shape, prev.fade.value);
          shapes.push(next);
        }
      }
      // Reduced motion: hold still and apply changes at once.
      if (reduceMotion.matches) {
        glides.rate.target = 0;
        for (const g of Object.values(glides)) snap(g);
        for (const shape of shapes) snap(shape.fade);
      }
    };

    const draw = () => {
      read();
      const size = frameInfo.size;
      if (size !== shownSize) {
        shownSize = size;
        wrapper.style.width = wrapper.style.height = `${size}px`;
        canvas.style.width = canvas.style.height = `${size}px`;
        const px = Math.round(size * dpr);
        if (canvas.width !== px) canvas.width = canvas.height = px;
      }
      ctx.setTransform(canvas.width / size, 0, 0, canvas.width / size, 0, 0);
      ctx.clearRect(0, 0, size, size);
      sceneNow.draw(ctx, frameInfo);
      ctx.globalAlpha = 1;
    };

    const tick = (now: number) => {
      const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
      last = now;
      let moving = false;
      const times: Partial<Record<string, number>> = latest.current.settle ?? {};
      const pauseTimes = latest.current.pause;
      for (const [k, g] of Object.entries(glides)) {
        // Stopping and starting take their own times; every other target its own, else `SETTLE`.
        const time =
          k === "rate"
            ? g.target > 0
              ? (pauseTimes?.start ?? START_SETTLE)
              : (pauseTimes?.stop ?? STOP_SETTLE)
            : (times[k] ?? SETTLE);
        if (stepGlide(g, dt, time)) moving = true;
      }
      const shapeSettle = latest.current.shape?.settle ?? BLEND_SETTLE;
      for (const shape of shapes) if (stepGlide(shape.fade, dt, shapeSettle)) moving = true;
      shapes = shapes.filter((shape) => shape.fade.target > 0 || shape.fade.value > 0);

      if (sceneNow.advance) {
        read();
        sceneNow.advance(dt, frameInfo);
      }
      draw();
      // Sleep once everything has settled and the animation is paused, or nobody can see it.
      frame = visible() && (moving || glides.rate.value > 0) ? requestAnimationFrame(tick) : 0;
    };

    const wake = () => {
      sync();
      if (frame || !visible()) return;
      last = 0;
      frame = requestAnimationFrame(tick);
    };

    const sleepOrWake = () => {
      if (visible()) wake();
      else {
        cancelAnimationFrame(frame);
        frame = 0;
      }
    };
    const observer = new IntersectionObserver(
      (entries) => {
        onScreen = entries[entries.length - 1].isIntersecting;
        sleepOrWake();
      },
      { rootMargin: "64px" },
    );
    observer.observe(wrapper);

    wakeRef.current = wake;
    reduceMotion.addEventListener("change", wake);
    document.addEventListener("visibilitychange", sleepOrWake);
    sync();
    draw();
    wake();
    return () => {
      cancelAnimationFrame(frame);
      wakeRef.current = null;
      observer.disconnect();
      reduceMotion.removeEventListener("change", wake);
      document.removeEventListener("visibilitychange", sleepOrWake);
    };
  }, []);

  const wrapperStyle: CSSProperties = { width: initialSize, height: initialSize, ...style };

  return (
    <div ref={wrapperRef} role="status" aria-label={label} className={className} style={wrapperStyle} {...rest}>
      <canvas ref={canvasRef} style={{ width: initialSize, height: initialSize, display: "block" }} />
    </div>
  );
}

/** Props every bar ring takes. */
interface BarSettings {
  bars: number;
  barHeight: number;
  barWidth: number;
  radius: number;
  extend: number;
  duration: number;
  stagger: number;
  size: number;
  color: string;
  minOpacity: number;
  paused: boolean;
  /** Which way the push carries a bar: away from the center, or toward it. */
  direction?: BarDirection;
  /** Waves travelling round the ring at once; only twin reads it. */
  heads?: number;
  /** How much has transferred (0–1); left out, transfer loops. Only transfer reads it. */
  progress?: number;
  /** Steps in the plan, each a segment of the ring. Only plan reads it. */
  steps?: number;
  /** The step running now, counting from 0; earlier steps show as done. Only plan reads it. */
  current?: number;
}

/** `out` pushes bars away from the center; `in` pulls them toward it. */
type BarDirection = "out" | "in";

/**
 * - `comet`: the wave snaps a bar longer and lets it fall back slowly, so a bright head drags a fading tail.
 * - `twin`: several waves, evenly spaced, travel round together, moving the bars.
 * - `read`: a small wave travels round at a steady pace, lighting bars more than it moves them, like a cursor down lines.
 * - `write`: bars are typed in bursts of four, each popping and leaving a short mark, until the ring is written; then
 *   the marks are wiped in the same order.
 * - `seek`: the wave runs forward, slows, backs up part of the way and runs on, like hunting for a match.
 * - `stream`: short pulses chase each other round with uneven gaps, like tokens arriving.
 * - `transfer`: bars fill clockwise to `progress`, the leading bar pulsing; with no `progress` it fills and drains on a loop.
 * - `ping`: a pulse leaves 12 o'clock both ways, meets at 6, waits, and comes back, like a request and its response.
 * - `plan`: the ring is cut into `steps` segments; done steps hold grown, the `current` one sweeps, the rest rest.
 */
type BarAnimation = "comet" | "twin" | "read" | "write" | "seek" | "stream" | "transfer" | "ping" | "plan";

const BAR_ANIMATIONS: BarAnimation[] = ["comet", "twin", "read", "write", "seek", "stream", "transfer", "ping", "plan"];

/** How each animation spends its push: `grow` stretches the bar's leading end, `rise` moves the whole bar. */
const BAR_SPEND: Record<BarAnimation, { grow: number; rise: number }> = {
  comet: { grow: 1, rise: 0 },
  twin: { grow: 0, rise: 1 },
  // Reading lights the bars more than it moves them.
  read: { grow: 0.35, rise: 0 },
  write: { grow: 1, rise: 0 },
  seek: { grow: 0, rise: 1 },
  stream: { grow: 1, rise: 0 },
  transfer: { grow: 1, rise: 0 },
  ping: { grow: 0, rise: 1 },
  plan: { grow: 1, rise: 0 },
};

/** Every number the drawing reads, as the latest props want it. */
function barTargets(s: BarSettings) {
  return {
    ...colorTargets(s.color),
    barHeight: s.barHeight,
    barWidth: s.barWidth,
    radius: s.radius,
    extend: s.extend,
    duration: s.duration,
    stagger: s.stagger,
    minOpacity: s.minOpacity,
    heads: Math.min(4, Math.max(1, s.heads ?? 2)),
    // 0 pushes outward, 1 pulls inward; it glides, so a switch eases the ring from one side to the other.
    inward: s.direction === "in" ? 1 : 0,
    // Whether a progress was given, so leaving it out glides back to the looping transfer.
    determinate: s.progress === undefined ? 0 : 1,
    progress: Math.min(1, Math.max(0, s.progress ?? 0)),
    steps: Math.min(8, Math.max(2, s.steps ?? 4)),
    current: Math.max(0, s.current ?? 1),
  };
}

type BarKey = keyof ReturnType<typeof barTargets>;

/** Seconds (roughly) each prop takes to glide: color and opacity fade quickly, geometry and timing take `SETTLE`. */
const barSettle: Partial<Record<BarKey | "size", number>> = {
  red: FADE_SETTLE,
  green: FADE_SETTLE,
  blue: FADE_SETTLE,
  alpha: FADE_SETTLE,
  minOpacity: FADE_SETTLE,
  barHeight: SETTLE,
  barWidth: SETTLE,
  radius: SETTLE,
  extend: SETTLE,
  duration: SETTLE,
  stagger: SETTLE,
  heads: SETTLE,
  inward: SETTLE,
  determinate: SETTLE,
  progress: SETTLE,
  steps: SETTLE,
  current: SETTLE,
  size: SETTLE,
};

/** The bar count, clamped to 12–72. */
function barCountOf(s: BarSettings) {
  return Math.min(72, Math.max(12, Math.round(s.bars)));
}

/** A bar count can't be fractional, so a change cross-fades the old ring out while the new one fades in. */
const barShape = {
  key: (s: BarSettings) => String(barCountOf(s)),
  build: barCountOf,
  settle: FADE_SETTLE,
};

/** How much of each animation is on screen (0–1). Animations left out are off. */
type BarMix = Partial<Record<BarAnimation, number>>;

const TAU = Math.PI * 2;

/** Share of a comet's push spent snapping out; the rest is the tail falling back. */
const BAR_COMET_ATTACK = 0.2;

/** Bars typed in one burst before the pause; four keeps a burst inside the 3–4 units that may move at once. */
const BAR_WRITE_BURST = 4;

/** How long a typed bar stays, as a share of its full push. */
const BAR_WRITE_INK = 0.35;

/** Bars a seek runs forward, then backs up, each round. It nets five bars on. */
const BAR_SEEK_AHEAD = 8;

const BAR_SEEK_BACK = 3;

/** Where each stream pulse sits round the lap: a burst of three, a pair, then a long gap, like tokens arriving. */
const BAR_STREAM_PULSES = [0, 0.07, 0.18, 0.41, 0.52];

/** How grown a finished plan step holds. */
const BAR_PLAN_DONE = 0.4;

function barClamp(t: number) {
  return Math.min(1, Math.max(0, t));
}

/** A raised cosine: a smooth bump with no jolt at rest or at the peak, so a wave reads as one swell. */
function barSwell(local: number, duration: number) {
  return local >= 0 && local < duration ? 0.5 - 0.5 * Math.cos((TAU * local) / duration) : 0;
}

/** Seconds each animation's loop takes, so its phase can advance by rate and stay put when timing changes. */
function barCycles(bars: number, v: Values<BarKey>) {
  const stagger = Math.max(0.01, v.stagger);
  const duration = Math.max(0.05, v.duration);
  return {
    // One lap is every bar taking its turn.
    wave: bars * stagger,
    // A looping transfer: fill clockwise, hold full for one push, drain in the same order, hold empty for one push.
    fill: 2 * ((bars - 1) * stagger + 2 * duration),
    write: barWriteTimes(bars, stagger, duration).cycle,
    // One seek round: run ahead at the wave's pace, then back up at two thirds of it.
    seek: (BAR_SEEK_AHEAD + 1.5 * BAR_SEEK_BACK) * stagger,
    // Out to 6 o'clock, wait two pushes, back to 12, wait two pushes before the next request.
    ping: bars * stagger + 4 * duration + duration,
    // One sweep through the current step.
    plan: (bars / Math.min(8, Math.max(2, v.steps))) * stagger + duration,
    // The transfer's leading bar pulses every four pushes.
    pulse: 4 * duration,
  };
}

/**
 * When a write types each bar: bursts of `BAR_WRITE_BURST` keystrokes `stagger` apart, with a burst-long pause between.
 * Once every bar is typed it holds for a pause, wipes the marks clockwise at twice the pace, and pauses again.
 */
function barWriteTimes(bars: number, stagger: number, duration: number) {
  const pause = BAR_WRITE_BURST * stagger;
  const burst = BAR_WRITE_BURST * stagger + pause;
  const lastKey = Math.floor((bars - 1) / BAR_WRITE_BURST) * burst + ((bars - 1) % BAR_WRITE_BURST) * stagger;
  const wipe = lastKey + duration + pause;
  return { burst, wipe, cycle: wipe + ((bars - 1) * stagger) / 2 + duration + pause };
}

/**
 * A ring of bars standing on an inner circle, counted clockwise from 12 o'clock. Each animation gives every bar a
 * push (0–1) from its place on the ring; `mix` says how much of each animation is on screen. It is read every
 * frame, so a switch glides one animation's pushes into the next.
 */
function barScene<S extends BarSettings, K extends string>(mix: (v: Values<K | BarKey>) => BarMix): Scene<S, K | BarKey, number> {
  // How far through its loop each clock has come (0–1). Advancing by rate keeps the motion in place while the
  // timing or bar count changes, and lets pausing coast to a stop.
  const phase = { wave: 0, fill: 0, write: 0, seek: 0, ping: 0, plan: 0, pulse: 0 };
  // Bars the seek has netted so far; each round moves it on by ahead − back.
  let seekBase = 0;

  return {
    advance(dt, { v, settings }) {
      const cycles = barCycles(barCountOf(settings), v);
      for (const k of ["wave", "fill", "write", "ping", "plan", "pulse"] as const) phase[k] = (phase[k] + (dt * v.rate) / cycles[k]) % 1;
      phase.seek += (dt * v.rate) / cycles.seek;
      if (phase.seek >= 1) {
        phase.seek %= 1;
        seekBase = (seekBase + BAR_SEEK_AHEAD - BAR_SEEK_BACK) % barCountOf(settings);
      }
    },
    draw(ctx, { v, size, layers }) {
      const height = Math.max(0, v.barHeight);
      const extend = Math.max(0, v.extend);
      const weights = mix(v);
      const center = size / 2;
      const inward = barClamp(v.inward);
      // Room is left outside for the farthest an outward push reaches, so it never carries past the canvas edge.
      // An inward push needs that room inside instead, so the ring sits further out.
      const inner = Math.max(1, center - height - extend * (1 - inward) - 1);
      const stagger = Math.max(0.01, v.stagger);
      const minOpacity = v.minOpacity;
      const heads = Math.min(4, Math.max(1, v.heads));

      ctx.fillStyle = rgb(v);
      ctx.translate(center, center);
      for (const { shape: bars, fade } of layers) {
        const step = TAU / bars;
        const cycles = barCycles(bars, v);
        // A bar never grows wider than its slot at the inner end, so neighbors can touch but not overlap.
        const width = Math.min(Math.max(0, v.barWidth), 2 * inner * Math.sin(step / 2));
        // A bar's push can't outlast the lap, and a twin's can't run into the next head.
        const duration = Math.min(cycles.wave, Math.max(0.05, v.duration));
        const twinDuration = Math.min(cycles.wave / heads, duration);
        const head = phase.wave * bars;
        const fillTime = phase.fill * cycles.fill;
        const drain = cycles.fill / 2;
        const writeTime = phase.write * cycles.write;
        const writes = barWriteTimes(bars, stagger, duration);
        // The seek head moves on screen, so both legs take the strong ease-in-out.
        const seekTime = phase.seek * cycles.seek;
        const ahead = BAR_SEEK_AHEAD * stagger;
        const seekHead =
          seekBase +
          (seekTime < ahead
            ? BAR_SEEK_AHEAD * easeInOut(seekTime / ahead)
            : BAR_SEEK_AHEAD - BAR_SEEK_BACK * easeInOut((seekTime - ahead) / (cycles.seek - ahead)));
        // The seek's bump is `duration ÷ stagger` bars wide, centered on the head, since it travels both ways.
        const seekWidth = duration / stagger;
        const pingTime = phase.ping * cycles.ping;
        const pingBack = (bars / 2) * stagger + 2 * duration;
        const steps = Math.min(8, Math.max(2, v.steps));
        const planTime = phase.plan * cycles.plan;
        const pulse = barSwell(phase.pulse * cycles.pulse, duration);
        const filled = barClamp(v.progress) * bars;

        for (let i = 0; i < bars; i++) {
          // Seconds since the wave's head passed this bar.
          const local = ((((head - i) % bars) + bars) % bars) * stagger;
          let grow = 0;
          let rise = 0;
          let glow = 0;

          for (const name of BAR_ANIMATIONS) {
            const w = weights[name] ?? 0;
            if (w <= 0) continue;
            let lift = 0;
            // How lit the bar is, when that differs from how far it is pushed.
            let light: number | undefined;
            switch (name) {
              case "comet": {
                // Snaps out on the strong ease-out, then falls back on its mirror image: the drop is quick right
                // behind the head and lingers at the end, so the tail fades out instead of cutting off.
                const u = local / duration;
                lift = u < BAR_COMET_ATTACK ? easeOut(u / BAR_COMET_ATTACK) : u < 1 ? 1 - easeOut((u - BAR_COMET_ATTACK) / (1 - BAR_COMET_ATTACK)) : 0;
                break;
              }
              case "twin":
                // Heads sit evenly round the ring; while the count glides, the newest head fades in.
                for (let h = 0; h < Math.ceil(heads); h++) {
                  const back = (h * bars) / heads;
                  const t = ((((head - i - back) % bars) + bars) % bars) * stagger;
                  lift = Math.max(lift, Math.min(1, heads - h) * barSwell(t, twinDuration));
                }
                break;
              case "read":
                lift = barSwell(local, duration);
                break;
              case "write": {
                const key = writeTime - (Math.floor(i / BAR_WRITE_BURST) * writes.burst + (i % BAR_WRITE_BURST) * stagger);
                if (key < 0) break;
                // A keystroke pops out on the strong ease-out and settles back to its mark; the wipe eases it away.
                const u = key / duration;
                const stroke = u < BAR_COMET_ATTACK ? easeOut(u / BAR_COMET_ATTACK) : 1 - (1 - BAR_WRITE_INK) * easeOut(barClamp((u - BAR_COMET_ATTACK) / (1 - BAR_COMET_ATTACK)));
                lift = stroke * (1 - easeOut(barClamp((writeTime - writes.wipe - (i * stagger) / 2) / duration)));
                break;
              }
              case "seek": {
                let d = (((seekHead - i) % bars) + bars) % bars;
                if (d > bars / 2) d -= bars;
                lift = Math.abs(d) < seekWidth / 2 ? 0.5 + 0.5 * Math.cos((TAU * d) / seekWidth) : 0;
                break;
              }
              case "stream":
                for (const at of BAR_STREAM_PULSES) lift = Math.max(lift, barSwell(((((local / stagger - at * bars) % bars) + bars) % bars) * stagger, duration));
                break;
              case "transfer": {
                // Determinate: full up to the progress, the part-filled leading bar pulsing so it reads as working.
                const part = barClamp(filled - i);
                const leading = i === Math.floor(filled) ? (1 - part) * pulse : 0;
                const loop = easeOut(barClamp((fillTime - i * stagger) / duration)) * (1 - easeOut(barClamp((fillTime - drain - i * stagger) / duration)));
                lift = v.determinate * (part + leading) + (1 - v.determinate) * loop;
                break;
              }
              case "ping": {
                // Steps count out from 12 o'clock both ways, so the request meets at 6 and the response comes back.
                const out = Math.min(i, bars - i) * stagger;
                lift = Math.max(barSwell(pingTime - out, duration), barSwell(pingTime - pingBack - ((bars / 2) * stagger - out), duration));
                break;
              }
              case "plan": {
                // Steps glide, so a change of step count slides the segment edges rather than jumping them.
                const at = (i * steps) / bars;
                const own = Math.floor(at);
                const into = (at - own) * (bars / steps) * stagger;
                const done = barClamp(v.current - own);
                const running = barClamp(1 - Math.abs(v.current - own));
                lift = done * BAR_PLAN_DONE + running * barSwell(planTime - into, duration);
                light = done + running * barSwell(planTime - into, duration);
                break;
              }
            }
            grow += w * lift * BAR_SPEND[name].grow;
            rise += w * lift * BAR_SPEND[name].rise;
            glow += w * (light ?? lift);
          }

          // Outward, a grow stretches the outer end and a rise moves the bar out; inward, the inner end stretches
          // toward the center and the bar moves in. Neither may cross the center.
          const length = height + extend * grow;
          const base = Math.max(1, inner + extend * rise * (1 - 2 * inward) - extend * grow * inward);
          const corner = Math.min(Math.max(0, v.radius), width / 2, length / 2);

          ctx.globalAlpha = v.alpha * fade * (minOpacity + (1 - minOpacity) * barClamp(glow));
          // Start at 12 o'clock and go clockwise; each bar points straight out from the center.
          ctx.save();
          ctx.rotate(i * step);
          ctx.beginPath();
          ctx.roundRect(-width / 2, -base - length, width, length, corner);
          ctx.fill();
          ctx.restore();
        }
      }
    },
  };
}
